"""Value coercion + producer re-invoke argument helpers.

Small, import-light helpers the correction dispatcher uses to apply a correction
by re-invoking the field's producer with a well-typed argument.
"""

from __future__ import annotations

from typing import Any, Dict

from rasa.mantle.memory.field import MemoryField


def coerce_to_field_type(value: Any, field: MemoryField) -> Any:
    """Coerce an LLM-supplied *value* to the field's declared type.

    The ``correct()`` schema accepts an untyped ``value`` (it spans fields of
    different types), so a boolean field may arrive as the string ``"true"``.
    Coercion is best-effort: on any failure the original value is returned and
    the producer/validator decides whether to accept it.
    """
    if not isinstance(value, str):
        return value
    declared = field.type
    text = value.strip()
    try:
        if declared == "bool":
            lowered = text.lower()
            if lowered in {"true", "yes", "1"}:
                return True
            if lowered in {"false", "no", "0"}:
                return False
            return value
        if declared == "int":
            return int(text)
        if declared == "float":
            return float(text)
    except (TypeError, ValueError):
        return value
    return value


def reinvoke_arguments(
    previous_arguments: Dict[str, Any], entry_name: str, value: Any
) -> Dict[str, Any]:
    """Build the producer arguments for a re-invoke with the corrected *value*.

    Producers conventionally take a single argument named after the field they
    fill (e.g. ``set_shipping_type(shipping_type=...)``), so:

    1. if *entry_name* is already an argument key, override it;
    2. else if the producer was called with exactly one argument, override that;
    3. else add *entry_name* as a new argument.
    """
    new_arguments = dict(previous_arguments)
    if entry_name in new_arguments:
        new_arguments[entry_name] = value
    elif len(new_arguments) == 1:
        only_key = next(iter(new_arguments))
        new_arguments[only_key] = value
    else:
        new_arguments[entry_name] = value
    return new_arguments
